cases.good:
// gather 3 query shapes in parallel, filter out extension URLs
const [a, b, all] = await Promise.all([
  chrome.tabs.query({ active: true, currentWindow: true }),
  chrome.tabs.query({ active: true, lastFocusedWindow: true }),
  chrome.tabs.query({}),
]);
return [...a, ...b, ...all].find(t => !t.url?.startsWith('chrome-extension://'));

